const MORE = {"abaddon":{"n":"Лорд Аверно","f":["Его сила идёт из Купели Аверно, древнего источника чёрного тумана под землями его рода.","Из-за этой связи с Купелью его ненавидят даже бессмертные демоны.","Враждует с Никс и её последним фанатиком, Nyx Assassin, и хвастается, что уже сразил нескольких её посланников.","Носит один из трёх клинков рода Аверно, выкованных в тумане Купели.","Прослышал, что существует второй источник тумана, и хочет найти его и забрать себе."]},"alchemist":{"n":"Раззил Темновар","f":["Род Темноваров веками занимался алхимией, но только Раззил замахнулся превратить в золото целую гору и угодил за это в тюрьму.","Сбежал вместе с огром-сокамерником, напоив его зельем ярости из тюремной плесени; с тех пор они путешествуют вдвоём.","Ингредиенты нередко добывает из тел врагов и с профессиональным интересом разглядывает необычное строение других героев.","Иногда всё ещё работает «силовиком» на семейное дело.","Огр устал его таскать и мечтает о новых ботинках и удобном седле.","Tinker считает алхимию лженаукой, а Hoodwink недолюбливает всех Кинов, включая Раззила."]},"ancient_apparition":{"n":"Калдр","f":["Не живое существо, а проекция того, что обитает в холодной пустоте, которая была до вселенной и дождётся её конца.","Считается одной из сильнейших сущностей мира наравне с Elder Titan и Ткачами.","По поверьям, чем ближе конец вселенной, тем сильнее и «моложе» становится Калдр.","Ходят слухи, что он неравнодушен к Crystal Maiden: Monkey King советует ему запастись шутками про снег."]},"antimage":{"n":"Магина","f":["Был всего лишь послушником монастыря Турстаркури, когда его уничтожил легион Мёртвого бога, но успел перенять часть монашеских приёмов.","После побега продолжает медитировать по их правилам и мучается виной выжившего: лица погибших братьев видит искажёнными.","Охотится на магов: на его счету чародей Хрот, оборотень Трошо и Сахск, которого он сразил по просьбе правителя Йоскрета.","Был посвящён в Племя Высоких песков и участвовал в безнадёжной обороне Бахваррена.","Хорошо знает текст Таэль'Ам, который учит сопротивляться Мёртвому богу.","Работал вместе с Silencer на Поместье Тайлер.","Раньше Terrorblade считался его братом, но Valve эту линию из игры убрала."]},"arc_warden":{"n":"Зет","f":["Третий осколок изначального разума: когда Свет и Тьма развязали войну, именно Зет запер их в Безумной Луне.","Когда тюрьма взорвалась, его разметало по космосу и раздробило на множество частей; отсюда и его двойник.","Называет себя «Самость», пола не имеет, и о нём говорят «оно».","Хочет разрушить обе крепости, чтобы раскол закончился и всё вернулось к единству.","Энергия его сородичей, Непримиримых камней, исказила его и пошатнула стремление к гармонии.","Ему служат призраки, которые помогают в обмен на энергию."]},"axe":{"n":"Могул Хан","f":["Оглоди, воин краснокожей расы, дослужившийся до командира армии Красного тумана.","После распада Красного тумана, возможно, примкнул к армии Кровавого тумана.","Не любит убивать других Оглоди, а вот Кинов ненавидит всех без разбора.","Однажды нанял барда, чтобы тот воспевал его подвиги.","Bristleback уважает его за стойкость, как и всех Оглоди."]},"bane":{"n":"Атропос","f":["Родился из кошмаров богини Никташи: ужас, который больше не умещался в её снах, вырвался наружу и стал Бэйном.","Один из Трёх Теней, бесплотных существ безумия, ужаса и смерти; их символ — паслён.","Grimstroke намекает, что тело Бэйна сделано из драгоценного ихора Никташи.","Tusk зовёт его «Мистер Грим».","Имя отсылает к мойре Атропос из греческих мифов, которая перерезает нить жизни."]},"batrider":{"n":"","f":["Родом из джунглей Йама Раскав, где выживает только сильнейший.","По легенде, мальчишкой его утащила гигантская летучая мышь, а он не только выжил, но и оседлал её.","Однажды в серных пещерах его мышь выбилась из сил и уцелела только благодаря встречному отшельнику.","Dark Willow бывала в Йама Раскав и отзывается о тех джунглях с презрением."]},"beastmaster":{"n":"Каррох","f":["Был в плену у последнего короля Слома и поклялся больше никогда не служить знати.","Снаряжение делает из того, что даёт природа: перьев, шкур, костей и меха.","Говорят, с бритой головой он лучше понимает зверей.","Дружит с Windranger, которая хвалит его тушёное мясо.","Вырос в Сломе вместе с Lycan."]},"bloodseeker":{"n":"Стригвир","f":["Родом из Ксакатокатля; связан кровной клятвой со своими богами, Бескожими Близнецами, и зовётся их гончей.","Раньше состоял в Охотниках за костями и носит доспехи из костей принесённых в жертву зверей.","Капюшон закрывает ему глаза, потому что вести его должны Близнецы.","В странствиях задержался в королевстве, где казнили через повешение, и долго наблюдал за палачами.","Демон Эстжок понемногу подчиняет его себе, забирая кровь, предназначенную Близнецам.","Dark Willow видела его в Розолисте, вероятно во время битвы Бронзового легиона с Красным туманом."]},"bounty_hunter":{"n":"Гондар","f":["Принадлежит к неизвестной кошачьей расе, детёнышей которой называют «котятами», и иногда говорит на своём языке.","По слухам, учился у легендарного охотника Сорука, от него и заклинание на клинках.","Выслеживает цель и по запаху, ставит ловушки и забирает трофеи с убитых как часть платы.","Связан с Калдинскими убийцами и состоит в Гильдии Панголинов.","Самый тяжёлый заказ в его жизни — Алый Глоткорез.","На скачках курьеров в Белом шпиле, по словам Pangolier, жульничает."]},"brewmaster":{"n":"Мангикс","f":["Сын Небожителя и смертной женщины; единственный из небесных духов, кто владеет сразу несколькими стихиями.","Выученик ордена Ойо, который в долине под Разрушенным городом постигает священное хмельное забытьё.","Обожает выпивку, но ром презирает.","Родня Storm, Ember, Earth и Void Spirit, а Шторма зовёт кузеном.","Мечтает когда-нибудь вернуться в Разрушенный город и быть там похороненным."]},"bristleback":{"n":"Ригварл","f":["Завсегдатай таверн между Сломом и Эльзе; скорее всего, оттуда и родом.","Говорит с простонародным акцентом, в английской версии это кокни.","Свой поршневой пронзатель получил от эксцентричного инженера Пинзика.","Главный соперник с севера — Tusk, но объединиться с ним он не против.","Кинов считает мелкими и слабыми, а Оглоди уважает за стойкость.","Dawnbreaker не в восторге от его внешности."]},"broodmother":{"n":"Арахния","f":["Её с паучатами почитал культ у горы Пиротей: верующие дарили ей броню, а потом сами бросались в её сети.","Однажды пощадила забредшего кузнеца в обмен на новый комплект доспехов.","Охотилась в Тернистых пустошах ради особой добычи для потомства.","Когда-то дружила с Monkey King и даже подталкивала его к Битве Древних, но они рассорились и стали врагами."]},"centaur":{"n":"Брэдводен","f":["Чемпион кентавров: победил всех соперников на арене Омекса и получил Великий пояс Омекса.","Считает бой высшим искусством, а взмахи клинка сравнивает с пением.","Хранит Рог Друуда, священную реликвию, которая созывает всех кентавров на войну.","Хочет быть похороненным на земле Омекса.","Земляк Disruptor из Друуда; восхищается Магнусом и вообще предпочитает компанию четвероногих."]},"chaos_knight":{"n":"","f":["Один из Предвечных, сил вселенной, появившихся, когда Elder Titan расколол мир; после смерти возвращается в Предвечный мир.","Самый старший и неутомимый из них; Enigma называет его сильнейшим.","Гонится за «заблудшим» Светом, и всё указывает на то, что это его брат Keeper of the Light.","Скачет на коне по имени Армагеддон и любое ездовое животное называет «лошадью», даже летучую мышь Batrider.","Pudge считает его снобом."]},"chen":{"n":"","f":["Родом из безбожных Хажадальских пустошей, где его кочевой клан приручал боевых подземных драконов.","Клан разгромили Церковные Рыцари, и пленённый Чен принял их веру.","Теперь он фанатичный рыцарь ордена и сам применяет в бою те методы, которые когда-то сломали его.","Пытается обратить в свою веру верховную жрицу Румусских верующих."]},"clinkz":{"n":"","f":["Был защитником Ховена; сгорел заживо, но продолжает патрулировать родные земли, хотя каждый шаг причиняет ему боль.","Его лук сделан из костей деда, и тот до сих пор «даёт советы» изнутри.","Победил демона Мараксиформа и сделал лук из его головы.","Часть снаряжения для него выковали маленькие кузнецы-смивилы."]},"rattletrap":{"n":"Ратлтрап","f":["Кин, как Tinker и Alchemist: малый рост восполняет механикой и смекалкой.","Потомственный часовщик: этим ремеслом занимались его дед и отец.","Броня, по словам Alchemist, работает на бензине, а под шлемом, похоже, прячется борода.","Близок с Tinker и Sniper и соперничает со Snapfire.","Hoodwink не любит его, как и всех Кинов."]},"crystal_maiden":{"n":"Рилай","f":["Младшая сестра Lina; вместе они шесть раз уничтожили родительский дом.","Училась у мага льда в Леднике Голубого Сердца; он вручил ей доспехи и посох, а сам ушёл спать в глубь ледника.","Мечтает однажды тоже вернуться на ледник и проспать тысячу лет.","В детстве играла в снежки с Tusk.","Её наставником, вероятно, был Пирпонт из Сапфирового совета; Pangolier намекает, что тот на неё надеялся.","Dark Willow считает, что сестёр рассорили родители.","Ходят слухи, что в неё влюблён Ancient Apparition."]},"dark_seer":{"n":"Иш'Кафэль","f":["Родом из «Земли за стеной» и застрял в чужом для себя мире.","Был генералом бога-короля Даматрикса.","Сражается разумом, а не мечом, и умеет вызывать призматическую стену.","Faceless Void завидует форме его головы, а Void Spirit сочувствует ему как пленнику чужого мира.","Oracle предостерегает его о тех, кто хорошо видит во тьме."]},"dark_willow":{"n":"Миреска Ветреная","f":["Фея из богатой семьи торговых королей Ревтела; ненавидела учителей и властного отца и сбежала из дома.","Путешествует с огоньком Джексом и хранит награбленное в своём дупле.","Разыскивается минимум в шести странах; за ней охотятся наёмные убийцы, в том числе Bounty Hunter.","Убивать её научил Лорлин Ласан, глава Общества Яшмы, но вступать в общество она не захотела.","Провела много времени в Железном тумане и видела, на что способны машины.","Pangolier считает, что она больше похожа на отца, чем думает."]},"dawnbreaker":{"n":"Валора","f":["Когда-то была вестницей Золотых Лордов, но теперь никому не служит; её молот зовётся Лучезар.","Проспала так долго, что за это время зажглись звёзды, которых она раньше не видела; от былой силы у неё осталась тысячная доля.","Золотые Лорды были одержимы охотой на Chaos Knight и хотели использовать силу Io, поэтому с Хаосом у неё старые счёты.","Истребляла порождений Первородной Ночи, отсюда вражда с Night Stalker.","Называет Keeper of the Light прадедушкой и помнит падение Континуума.","Сделана не из материи этого мира: не ржавеет, зато может утонуть.","Знает Безликих, Наблюдателей и Ткачей, а Void Spirit, по её словам, заметно постарел."]},"dazzle":{"n":"","f":["Жрец теней ордена Дезун, прошедший испытание в мире Нотл.","Старейшины ордена подозревают, что он вернулся из Нотла не целиком: в его глазах видна тревога того полузабытого мира.","Huskar зовёт его кузеном, но обижен на него за то, что Даззл вернул его из Нотла.","В джунглях Феллстрата нашёл бабочек, которые питаются энергией Нотла."]},"death_prophet":{"n":"Кробелус","f":["Её кровь выцвела до эктоплазмы, и этими «чернилами» она записывает свои пророчества.","Призываемые ею духи — осколки её собственных прошлых жизней.","Возможно, ослепла, потому что заглянула в будущее слишком далеко.","Так часто пересекала завесу смерти, что цепляющиеся за неё души сплелись в её платье.","Училась у загадочной «Невесты Смерти», от которой остались только слухи и пара семейных реликвий.","Говорит, что уже много раз видела поле Битвы Древних во снах."]},"disruptor":{"n":"","f":["Оглоди, но в отличие от сородичей рассудителен и не склонен убивать без разбора.","Обижается, когда его связывают с жестоким Красным туманом и его предводительницей Сорлой Хан.","Axe не прочь драться с ним плечом к плечу, Bristleback уважает за стойкость.","Земляк Centaur из Друуда; Dawnbreaker восхищается тем, как он обуздал такую мощь."]},"doom_bringer":{"n":"Люцифер","f":["Говорит на демоническом языке Озкавош, где его имя звучит как Люцифаш.","Его зовут «Тем, кто горит и не сгорает»; он единственный, кто свободно ходит между Семью кругами ада.","Shadow Fiend когда-то сидел у него в яме и клянётся никогда туда не вернуться.","Elder Titan не встречал ничего подобного ни в одном из Семи миров.","Наслаждается болью слабых противников, которых потом поглощает.","Pudge считает, что Дум куда приятнее, чем о нём говорят."]},"dragon_knight":{"n":"Дэйвион","f":["Рыцарь, в котором после схватки живёт дух древнего эльдвурма Слайрака; эта линия подробно раскрыта в сериале «Кровь дракона».","По сериалу, Invoker приютил его с Мираной и Марси в своей башне и рассказал, что Древние драконы — восемь столпов творения.","В сериале между ним и Мираной возникает взаимная симпатия.","Эльдвурмы — древняя раса драконов-мудрецов, дышащих огнём, льдом и ядом; их историю хранят эпосы и эдды."]},"drow_ranger":{"n":"Траксекс","f":["Живёт уединённо, её зовут Одинокой Путницей; бывает, разговаривает сама с собой.","Нашла в тайной пещере под лесной поляной древний лук из светящихся кристаллов.","Состоит в Северном дозоре и чуть не вступила в Лесную стражу — ради их стильных перчаток.","Поклоняется божественному духу совы: однажды он приснился ей, и она проснулась с новым луком в руках.","Спускалась к сородичам-дроу и по всем правилам этикета выпросила ветвь священного Древа Кровавого Корня.","Главная соперница — Windranger: они вечно спорят, кто из них лучшая лучница, хотя вместе побывали в Калаборе."]},"earth_spirit":{"n":"Каолин","f":["Брат Ember, Storm и Void Spirit и кузен Brewmaster.","Верит в круговорот жизни и перерождение.","Поклоняется неизвестной богине и, возможно, сам её воплощение; Grimstroke дразнит его марионеткой.","Называет Nature's Prophet «своим пророком» и говорит, что знает истинную природу Tiny.","Grimstroke презирает его, как и других духов, за какое-то бедствие, обрушенное на Ашкавор.","По словам Dawnbreaker, он гораздо моложе своего брата Иная."]},"earthshaker":{"n":"Рейгор Каменное Копыто","f":["Безымянное бессмертное существо горы Ишай, которое спало в недрах, пока его не разбудило землетрясение; рога он отрастил себе сам.","Скучает по гаргульям Ишая и хранит Красную гору; тотем, заряженный Солнцем и Луной, направлен против Сил Тьмы.","Помнит гибель «сестры Земли» — другой планеты; её осколок слился с ним и пробуждает в нём новую силу.","Чувствует приближение существа, которое уничтожило ту планету, и готовится к встрече: просит Io и Arc Warden помочь с путешествием по космосу.","Дружит с Io и понимает его лучше других.","Pangolier ворчит, что он слишком часто говорит «Let's roll» и одержим Blink Dagger."]},"elder_titan":{"n":"","f":["Существует одновременно во всех Семи мирах; свой астральный дух зовёт «теневой душой».","Мечтает вернуть мир к Единству и Великой Симметрии, существовавшим до раскола.","Помнит Treant Protector ещё саженцем, а Earthshaker — «творцом континентов», который его забыл.","Глубоко уважает Lone Druid.","Собирает реликвии, включая осколки Кузниц вирмов.","У него есть только одна попытка возродить разрушенный мир, и он уверен в своих расчётах."]},"ember_spirit":{"n":"Син","f":["Воин-поэт, проповедующий равновесие и гармонию; на уроках использовал раскалённые цепи.","Брат Earth, Storm и Void Spirit и родня Brewmaster.","Вернул себе пару рапир-реликвий из Крепости Непослушного пламени.","Разослал свои огненные копии с песчаной бурей искать тех, кто ещё хранит учение Стража Пламени.","В прошлой жизни тренировался вместе с Juggernaut.","Grimstroke его презирает, Hoodwink считает убийцей, а Monkey King ждёт от него объяснений за какой-то поступок."]},"enchantress":{"n":"Аюшта","f":["Весёлая и добродушная, но браконьеров ненавидит и придумала против них особые средства.","Недолюбливает полководцев, разоряющих природу.","Когда-то работала вместе с Pangolier.","Lone Druid намекает, что она забыла свою «истинную форму».","Hoodwink зовёт её тётушкой, Terrorblade зачем-то называет себя её лучшим другом, а Windranger и Dawnbreaker считают её милой."]},"enigma":{"n":"","f":["Предвечный, повелитель гравитации; после смерти возвращается в Предвечный мир.","Однажды его призвал алхимик Седрик, одержимый идеей стать богом, — по записям другого алхимика, помешанного на силах вселенной.","Dark Willow мечтает о его силе и подлизывается, чтобы выведать секреты.","Timbersaw жалуется, что на него и так слишком «давят», а Pudge считает Энигму снобом."]},"faceless_void":{"n":"Дарктеррор","f":["Послушник культа бога Класза; глаз, возможно, лишился при посвящении.","После смерти возвращается в Класзурем, а за поражение в нашем измерении там его ждут неприятности.","Видит будущее и, по его словам, видел, где кончается река времени; считает, что нынешняя эпоха последняя.","Носит доспехи из хронита и за свою жизнь сменил множество обликов.","Puck уверяет, что жители Класзурема с облегчением избавились от него.","Dark Willow украла у него песочные часы Класзурема, а он до сих пор не заметил пропажу."]},"grimstroke":{"n":"","f":["Был жрецом Ашкавора; провалив ритуал Вознесения, обрушил на свой народ чернильный прилив.","Уцелевшие ашкаворцы превратились в тёмных призраков, а оставшихся Вознесённых он пытается подчинить.","Его возлюбленная Яови тоже стала фантомом и теперь служит ему в бою.","С юности учился рисованию кистью и ценит искусство, книги и древности.","Обожает чужие тайны и всегда расспрашивает о секретах; сам утверждает, что его народ получил то, что заслужил."]},"gyrocopter":{"n":"Аурел","f":["Кин, как Tinker и Clockwerk.","Терпеть не мог своё прошлое начальство.","Связан с Университетом Ультимира, который построил для него атомный двигатель.","Monkey King ненавидит его вместе с его шумной машиной, а Hoodwink — как и всех Кинов."]},"hoodwink":{"n":"Прохвостка","f":["Выросла в смертельно опасных лесах Томо'кана, где монстры с щупальцами страшнее любых солдат.","Мастер выживания: прячет тайники, держится у безопасных мест и умеет быстро пробираться сквозь чащу.","Называет себя вегетарианкой.","Ненавидит Кинов (Tinker, Techies, Clockwerk, Sniper, Snapfire, Alchemist, Timbersaw) — за то, что их города и машины губят леса.","Однажды пыталась освободить сестру, работавшую на чужих полях, подожгла посевы, но бригада просто разбежалась.","Не любит полководцев вроде Dark Seer и Legion Commander, Enchantress зовёт тётушкой и сочувствует Grimstroke."]},"huskar":{"n":"","f":["Священный воин ордена Дезун, переродившийся после мучительного испытания в мире Нотл.","Жизненную силу ценит превыше всего, а зависимость от маны считает нечестивой.","Вернулся из Нотла с тайнами, которых не знали даже старейшины.","Зовёт Dazzle кузеном, но обижен на него за возвращение из Нотла.","Уважает Bloodseeker и Witch Doctor, а Troll Warlord презирает его, потому что видит в нём себя."]},"invoker":{"n":"Карл","f":["Не любит, когда его зовут настоящим именем — а Undying, Mirana и Queen of Pain зовут именно так.","Был лучшим учеником академии древнего волшебника, где была запрещена любая религия, и украл из архивов учителя опасную магию.","Rubick вспоминает, что раньше его знали как «Арсенального мага», а Puck помнит его с давних времён.","Один из немногих, кто помнит забытый орден Корумитов и знает их заклинания.","Gyrocopter считает, что Инвокер старше его минимум в сто раз; Juggernaut восхищается его ясным умом.","В сериале «Кровь дракона» раскрыт как любящий отец, а не только высокомерный маг."]},"wisp":{"n":"Висп","f":["Предвечный: сила вселенной, появившаяся при расколе мира; после смерти возвращается в Предвечный мир.","Не говорит словами: его эмоции звучат музыкой — радость в мажоре, гнев резким диссонансом.","Дружит с Earthshaker, который понимает его лучше других и просит помочь добраться до другого мира.","Puck хвалит его едкое чувство юмора и не одобряет его союз с какой-то могущественной силой.","Earth Spirit говорит, что черпает силы из того же источника, что и Висп."]},"jakiro":{"n":"","f":["Пироксианский дракон, родившийся с двумя головами; сородичи сторонились его и даже охотились на него.","Из ярости изгнанника выковал силу, способную уничтожать хоть драконов, хоть демонов.","В пещерах Речного заповедника детям в День костров рассказывают о нём как о благородном защитнике.","А народ мерансов помнит его как двухголового демона, который сжёг почти весь их отряд у утёсов Гроща."]},"juggernaut":{"n":"Юрнеро","f":["Последний из Джаггернаутов, мечников с Острова Масок, который ушёл под воду.","Поклоняется богам острова и совершал паломничества в Храмы Масок.","Бросил вызов продажному лорду, был объявлен предателем и изгнан без права на благородную смерть.","Коллекционирует мечи и доказывает мастерство в охоте на огромных зверей.","Templar Assassin — его бывшая, а Pangolier советует ему извиниться.","Sven однажды разрубил его маску клинком Adjudicator и пробудил в ней души предков."]},"keeper_of_the_light":{"n":"Эзалор","f":["Предвечный, сила Света; после смерти возвращается в Предвечный мир.","Первым покинул прародительский мир и нарушил «Первое соглашение», поэтому Chaos Knight считает его изгоем и охотится на него.","Создатель древних солнц: в начале своего пути вложил энергию в крылатого вестника, чей галоп зажигал солнца на каждом небосводе.","Неравнодушен к героиням и не упускает случая сделать комплимент.","Dawnbreaker зовёт его прадедушкой и сомневается, что ему вообще есть дело до того, чтобы всё исправить."]},"kunkka":{"n":"Адмирал Кункка","f":["Бывший адмирал Кладдского флота, из семьи моряков-гарпунщиков; прошёл битву у порта Мигнин и обе битвы у Дрожащего острова.","Владеет легендарным мечом Tidebringer.","После второй битвы его выбросило на берег земель Кинов, и там он снова возглавил флот.","По слухам, разрубил море, нашёл Мэльрона и отсёк ему щупальце.","Не пират, но драгоценности при случае прибирает; трубку не вынимает изо рта на удачу.","Неизвестно, жив ли он или на поле боя сражается его призрак, пленённый ритуалом магов-фаталистов.","Вражда с Tidehunter началась у Дрожащего острова, когда тот призвал Мэльрона и потопил оба флота; при этом Кункка его уважает.","Винит Dark Willow в потере флота: она пробралась на его корабль за сокровищами."]},"legion_commander":{"n":"Тресдин","f":["Командир Бронзового легиона Стоунхолла; защищала город от Орды Бездны во главе с Врогрошем (Underlord).","Отобрав у Квита демонические клинки, выучила язык демонов Озкавош.","Под её командованием легион пытался удержать Красный туман в Розолисте и проиграл; её решения там считают роковыми.","Участвовала в захвате многих городов, и Dark Willow считает её правление тираническим.","Лидер мятежных воулов Рикс мечтает её убить, а Pangolier подтрунивает над её прошлой любовью к Белесанно.","Не доверяет почти никому: магам, демонам, драконам, деревьям, инженерам, нежити — зато восхищается усами."]},"leshrac":{"n":"Истерзанная душа","f":["Каждое мгновение существования для него мука, и он желает, чтобы всему поскорее пришёл конец.","Овладел посохом с осколком проклятого хроноптического кристалла, энергия которого питает его духов горя.","Однажды что-то сделал с подругой Pangolier, и тот поклялся убить его при следующей встрече.","Презирает почти всех двуногих и придирчив к числу ног: Enchantress, по его мнению, позорит четвероногих."]},"lich":{"n":"Этриан","f":["При жизни был магом льда и порабощал целые королевства, пока подданные с отчаявшимися магами не сковали его и не утопили в Чёрном озере.","Год опускался на дно и повис на уступе — мёртвый, но нетленный, пока его не выловил геомант Анхил.","Мятежники приковали к его спине книгу заклинаний и надели ослепляющую корону, чтобы он больше не читал тёмных знаний.","Всю жизнь гнался за Короной витой крови, которую не может носить ни одно живое существо.","Говорит, что у него остались дела в Розолисте."]},"life_stealer":{"n":"Н'эйкс","f":["Бывший узник знати Деварка, переживший бесконечные пытки и потерявший рассудок.","В его теле слились два сознания; иногда он вспоминает «Мастера» — волшебника, с которым делил камеру.","Bristleback считает его Оглоди и уважает за стойкость.","Свою жуткую броню заказал опальному ученику колдуна — нормальный колдун за такое не взялся бы.","Dawnbreaker находит, что он похож на чьего-то питомца."]},"lina":{"n":"","f":["Старшая сестра Crystal Maiden; соперничают с детства, и Dark Willow винит в их ссоре родителей.","В детстве у неё часто загорались волосы, и это до сих пор случается, когда она злится.","Училась огненному искусству у последователей Богини Солнца в Искрящейся пустыне; те считали её волосы благословлёнными светом.","Возможно, сама не знает, что одарена драконьим поцелуем.","Очень популярна в пустыне: Повелитель Мизрула подарил ей платье, чтобы она достойно выглядела перед его сыном.","Pangolier и Monkey King откровенно за ней ухлёстывают."]},"lion":{"n":"","f":["Пастушок, которого семья отдала в ученики великому мастеру демонологии; сам стал магистром, сражавшимся на стороне света.","Попытался обхитрить демона ради запретных знаний, был проклят и обращён в демоническую тварь.","С каждой отнятой жизнью его плоть меняется всё сильнее, а в магию просачивается демоническая природа.","Просит убежища в Плачущей Розе, потому что за ним охотятся Anti-Mage и Двор Ристула.","Расправился со святителем Видмаром из Ордена Кристального эшелона прямо в его храме.","Pangolier его терпеть не может, а Visage требует вернуть его в ад."]},"lone_druid":{"n":"Силла","f":["Мудрец и провидец древнего Друидского клана Медведя; силы природы выбрали его своим хранителем.","Его призрачный медведь — проекция его собственного духа, и облик медведя меняется вместе с настроением Силлы.","Победил злобное рогатое существо Захрикса, вторгшееся в его лес.","Когда-то учил Ursa и по неизвестной причине лишился из-за него пальца.","Охотится на волков, поэтому враждебен к Lycan; Hoodwink считает его медведя милашкой."]},"luna":{"n":"","f":["Военачальница богини Селемены и член Ордена Тёмной Луны; почти полностью в её власти.","Ездит на пантере по имени Нова, которая однажды чуть её не убила.","В сериале «Кровь дракона» вела армию Селемены против лесных эльфов и безжалостно их истребляла.","Служит вместе с Mirana, но той достался более высокий титул, и Луна этим недовольна.","Mars называет её овцой на службе Селемены, у неё репутация бессердечной."]},"lycan":{"n":"Бейнхаллоу","f":["Наследник разорённого Дома Амбри; на остатки семейных ценностей заказал у чародейки оружие для мести.","Ищет компанию других оборотней, хотя сородичи по проклятию не всегда ему рады.","Monkey King обещал помочь ему восстановить Дом Амбри.","Дружит с Windranger, а Juggernaut сочувствует ему как такой же последний из своего рода."]},"magnataur":{"n":"","f":["Его молот — на самом деле треснувшая наковальня, на которой поколениями ковали оружие.","Любит пофлиртовать и особенно неравнодушен к Enchantress.","Умеет сказать нужное слово в нужный момент.","Centaur глубоко его уважает."]},"marci":{"n":"","f":["Немая служанка и телохранительница Mirana; общается свистом.","Подружилась с принцессой ещё в детстве, и от неё же получила свою силу.","Хорошо относится к Dragon Knight; вся её история пришла из сериала «Кровь дракона»."]},"mars":{"n":"","f":["Бог войны, отрёкшийся от прежнего имени и наследия ради собственной империи.","Сын Zeus и Геры, племянник Посейдона и Аида; копьё ему выковал Вулкан. Мечтает свергнуть пантеон отца и ненавидит молнии.","Прошёл множество войн, включая Стигийские завоевания и походы против Континуума.","Перебил Пепельный легион, бросивший ему вызов; теперь их нежить по его зову образует Арену Крови.","Однажды убил своего наставника и требует жертвоприношений.","Dawnbreaker — его бывшая."]},"medusa":{"n":"Горгона","f":["Держит сад из окаменевших героев.","Её лук сделан из дерева и кристаллизованного яда гадюки из джунглей Йама Раскав.","Знакома с Zeus и его братьями.","Pangolier пообещал помочь ей найти сестёр.","Чем чаще она пользуется силой рода, тем дальше уходит от прежней жизни."]},"meepo":{"n":"","f":["Из неизвестной расы и большой семьи; работяга, который не прочь подработать могильщиком.","Годами копал в Овраге Певцов в поисках звучного кристалла и добывает руду сил Света.","Вместо оружия сойдёт что угодно: лопата, сковородка на палке, гаечный ключ или фонарь.","Играет на квадратной лютне вместе со своими копиями и продаёт страшные истории об Ущелье теней.","Задолжал Обществу Яшмы, поэтому за ним охотится Лорлин Ласан; любит ставки на скачках курьеров.","Мечтает о самоцветах Rubick, выполняет заказы для Bounty Hunter и неравнодушен к рыженьким."]},"mirana":{"n":"Принцесса Луны","f":["Ездит на огромной кошке по имени Саган; однажды нашла и грифона в Серебристом лесу.","Молится в Храме Мине, где ей являются видения.","В отличие от Luna, не состоит в Ордене Тёмной Луны.","В сериале «Кровь дракона» охраняла священные лотосы Селемены, упустила воровку и отправилась их возвращать — так и встретила Dragon Knight.","Её телохранительница — Marci, а дядя давно разыскивает её."]},"monkey_king":{"n":"Сунь Укун","f":["Великий Мудрец из «Путешествия на Запад»: родился из волшебного камня, принимает 72 облика и превращает волоски в клонов.","Свой посох добыл у Короля Восточных морей в тёмных глубинах.","Узнаёт в Pudge своего спутника Чжу Бацзе, а в Sand King — Ша Уцзина.","Когда-то был близок с Broodmother, а теперь они враги; однажды побил Beastmaster.","Ненавидит богов и духов, особенно Ember, Earth и Storm Spirit, и презирает почти всех животных, кроме обезьян.","Болтлив, хитёр, знает чужие истории и любит дразнить героев их старыми ссорами; мечтает оседлать дракона."]},"morphling":{"n":"Водный элементаль","f":["Поклоняется морской богине Полиморфии.","Существует одновременно в Астральном и Земном мирах, как и его клинки — одновременно материальные и призрачные.","На землю его заманили обещанием короны из руды сил Света.","Носит броню, подаренную Биротом Глубоководным.","Dawnbreaker сообщает, что его хозяева в ярости из-за его исчезновения."]},"naga_siren":{"n":"Слизис","f":["Стражница Глубин, как и Slardar: в первой же службе отличилась в битве у ворот Каменной рыбы и получила высшую награду змееногих.","После победы при Крее у неё украли чашу с драгоценностями, и за эту пропажу её изгнали; с тех пор она в одиночку ищет чашу, ожесточившись.","Давняя подруга Shadow Shaman.","Windranger утешает её: она своими глазами видела гибель Силтбрейкера, врага, у ворот Каменной рыбы."]},"furion":{"n":"Пророк Природы","f":["Избранный сын лесной богини Веродиции: вырос из последнего её семени, благословлённого её последним словом.","Его братья и сёстры — первые жители священного леса, четвероногие энты, похожие на Enchantress.","Сражался рядом с древней хранительницей леса Виргой Истинной Корой против Железного Принца.","Победил в тайном поединке героя речных земель Кастора Двубивня.","Характер у него, как у природы: то кроткий и заботливый, то беспощадный к тем, кто поднимает топор на его рощи."]},"necrolyte":{"n":"Ротунд'йер","f":["Был священником собора Румуска и неожиданно стал кардиналом, когда чума выкосила его начальство.","Вместо помощи больным наживался на них, выманивая богатства в обмен на «духовные награды».","Сам себя зовёт Повелителем Чумы, Владыкой Мора и Тёмной Гнилью, но при этом всегда весел.","Ходит на грани жизни и смерти, переходя туда и обратно с помощью душ своих жертв; его коса скована из замученных душ.","Обожает Pudge и не может его ненавидеть, а Omniknight презирает как чистоплюя.","Собирается заразить чумой армию Красного тумана; за ним охотятся леди Аншу и Pangolier."]},"night_stalker":{"n":"Баланар","f":["Последний из порождений изначальной Ночи, которые правили миром до того, как зажглось солнце.","Когда-то был скован проклятыми цепями Ордена Рахул, но вырвался, едва наступила тьма.","Его братья погибли в Первый день, но их души всё ещё бродят на краю пустоты.","Носит регалии, которые выковали его жертвы, пытаясь задобрить властителей ночи."]},"nyx_assassin":{"n":"","f":["Скарабей-фанатик, служащий богине Никс; живёт в Скрытом улье.","Умеет передавать свои мысли и слышать чужие — так он выслеживает врагов и общается.","Считает, что существа без хитинового панциря не приспособлены к жизни, и не берёт взяток.","Ненавидит Abaddon с тех пор, как появилась его каста; Broodmother хвастается, что съела немало его сородичей.","Templar Assassin и Void Spirit пытаются переманить его к себе на службу.","Однажды закопался так глубоко, что его панцирь покрылся кристаллами."]},"ogre_magi":{"n":"Аггрон Стонбрейк","f":["Две головы постоянно спорят друг с другом и считают себя вдвое умнее любого одноголового.","Богиня Удачи поручила ему присматривать за стаей огненных жаворонков; одна из птиц, Флокхарт, стала его скакуном.","Дружит с Tusk, который всегда рад видеть его в команде."]},"omniknight":{"n":"Ревнитель Громобой","f":["Крестоносец бога Всезнания; суров и любит бесконечно спорить с неверующими.","Носит шлем первых рыцарей, благословлённых Всезнанием, и молот, восстановленный по свиткам Эмарака.","Вторая по важности добыча Chaos Knight после Keeper of the Light.","Подумывает о союзе с богиней Селеменой.","Dawnbreaker слышала о нём много дурных слухов, Pangolier с ним спорить не хочет, а Necrophos его презирает."]},"oracle":{"n":"Нериф","f":["Был оракулом последнего из Высеченных королей; его пророчество перед битвой сбылось буквально — победа и поражение случились одновременно, и реальность раскололась.","Короли сошли с ума, а советники связали Нерифа и выбросили из своей вселенной на барке, плывущей между измерениями.","Видит будущее в звёздах; каждая его смерть в другом мире служит ему предупреждением в этом.","Сёстры Вуали послали Phantom Assassin убить его, но он предложил ей сделку и подарил парные клинки."]},"obsidian_destroyer":{"n":"","f":["Из камня сделан целиком или частично."]},"pangolier":{"n":"Донте Панлин","f":["Весёлый бродяга из благородной семьи; в юности его чешуйки были мягкими и затвердели с возрастом.","Состоит в Ниванских франтах, фехтовальщиках, живущих ради приключений и борьбы с несправедливостью; учился у Этьена Ловкостража и получил его мушкет.","Живёт по кодексу чести, против угнетения и рабства, и не одобряет жестокости ради жестокости.","Убил немало демонов, а мага Ворна хотел прикончить сам, но Phantom Lancer его опередил.","Был объявлен преступником во многих землях, но так ни разу и не попался.","Любит свести и помирить других: от Lina с Crystal Maiden до Juggernaut с Templar Assassin."]},"phantom_assassin":{"n":"Мортред","f":["Лишь одна из многих Призрачных убийц Сестёр Вуали; выполняет приказы оракула ордена.","Сёстры держат своих учениц в узде, предсказывая каждой её смерть.","Её парные клинки выковал мастер Кралер, а получила она их от Oracle, которого её послали убить.","Носит с собой список целей и, по словам Monkey King, получает удовольствие от убийств.","Dark Willow считает, что Сёстры просто её используют, а Dawnbreaker предлагает помочь найти настоящих родителей."]},"phantom_lancer":{"n":"Азраф","f":["Родом из деревни Поул; победил мага Ворна, но домой не возвращается — его иллюзиям там нет места.","Копьё с заговорённым кристаллом Ворна помогает ему направлять иллюзии на одну цель.","Случайно научился на миг собирать себя в совершенное единство и теперь думает только о том, как растянуть этот миг.","Любит читать нотации, особенно Dark Willow; давний друг Juggernaut."]},"phoenix":{"n":"","f":["Космическое существо, которое любит полёты в верхних слоях атмосферы.","Далёкий потомок Keeper of the Light; Dawnbreaker называет его юным лордом с искрой Золотых Лордов.","Arc Warden видел его свет на космических путях.","Несмотря на звериный вид, прекрасно разбирается в торговле.","Dark Willow мечтает о его огненном пере."]},"puck":{"n":"Волшебный дракончик","f":["Вылупился на листьях Древа глубин и для начала съел всех своих братьев и сестёр.","Его крылья живут чуть не в такт с остальным телом в этом мире.","Кровь волшебных драконов редкая и ценится алхимиками — Alchemist в восторге.","Бывал в Класзуреме, мире бога Класза, и знает свитки Хейза.","Понимает Io и Spectre, а Dark Willow устала от его вмешательства в её дела."]},"pudge":{"n":"Мясник","f":["В юности был королевским мясником у кровавого короля Брандалона и считает те годы лучшими.","Ест почти любое мясо, однажды съел чёрного дракона; сырую рыбу «настоящим мясом» не считает.","Никогда не спит и злится, когда спрашивают о его семье.","Нашёл в разломе одержимые Цепи, когда-то выкованные против слуг Мёртвого бога; цепи сами потянулись к нему.","Когда-то держал канавного борова как лучшего друга, но в итоге съел.","Старый соперник Rubick, но считает его неплохим парнем."]},"pugna":{"n":"","f":["Ребёнок из монастыря Забвения, черпающего силу из Нижних пределов; монахи признали его новым воплощением своего настоятеля.","Держал Viper как питомца, пока тот не вырвался и не ослепил старого заклинателя.","Служит проводником Икс'екса Разрушителя, который стал слишком тучным, чтобы пройти в наш мир.","Его вард черпает силу из Пределов пустоты и существует сразу в двух мирах.","По словам Alchemist, светится потому, что полон фосфора."]},"queenofpain":{"n":"Акаша","f":["При Ристульском дворе её считают лишь сестрой демона Б'Кора.","Заключила сделку с изгнанным принцем-демоном Ногхом: он отрёкся от титула, а она унаследовала его земли и силу.","Собирается отомстить Shadow Fiend, Underlord и Б'Кору и стать королевой двух миров.","Wraith King добивается её, но она не отвечает взаимностью.","Говорит, что помнит Tinker; Pangolier подшучивает над её нарядами."]},"razor":{"n":"Надзиратель Лабиринта","f":["Страж Узкого лабиринта: вписывает имена в Книгу мёртвых, а бросивших ему вызов выбрасывает между измерениями.","Его электричество украдено у самых яростных бурь.","Выжившие описывают его каждый по-своему — похоже, он меняет облик.","Его самый давний враг — Storm Spirit, а Mars считает его скучным бюрократом."]},"riki":{"n":"Рикимару","f":["Последний сын династии Талин: в день предательства сбежал, переодевшись стражником, и подобрал кинжал с тела отца.","Носит в одежде кусочек короны матери и бережёт фамильные клинки с гербом дома.","Берёт контракты, но деньги никогда не возвращает.","Был связан с Обществом Яшмы и Лорлином Ласаном; Dark Willow выбрала другой путь, и они отдалились.","Его родина славится ароматными пряностями — Pangolier сразу это замечает."]},"rubick":{"n":"Великий Маг","f":["Сын великого мага Аганима, создателя Скипетра, и до сих пор живёт в его тени.","Долго бился над загадочным посохом-головоломкой и, разгадывая его, заставляет врагов зависать в воздухе.","Знает трюк с четырёхмерным пространством, о котором не догадывался даже Аганим.","Иногда странствует как учёный.","Старый соперник Pudge; Meepo мечтает о его самоцветах, а Dark Willow — о тайнах его посоха."]},"sand_king":{"n":"Криксалис","f":["Его тело создали Колдинские джинны.","Носит ядовитый наруч владыки Пустошей, зачарованный так, что даже царапина становится смертельной.","Monkey King узнаёт в нём Ша Уцзина из «Путешествия на Запад»."]},"shadow_demon":{"n":"","f":["Говорит на демоническом языке Озкавош.","После вмешательства Doom и Shadow Fiend вернулся к бытию и собрал себя из неидеальных, но рабочих частей.","Собирал культ последователей для своего замысла и переманивает смертных подарками — Dark Willow их не принимает.","Shadow Fiend когда-то служил ему из-за долга, а потом вместе с Doom разрушил его культ."]},"nevermore":{"n":"Невермор","f":["Демон, служащий неизвестному господину и говорящий на Озкавош.","Когда-то сидел в яме у Doom и служил Shadow Demon, но вырвался из обоих долгов и даже объединился с Doom, чтобы разрушить культ Теневого Демона.","Начал поглощать души других демонов, и они изменили его облик.","По истории Artifact, входил в Ристульский двор и дал силу командиру воулов Риксу в войне с Бронзовым легионом.","У него есть стая учеников, которые заключают сделки со смертными там, где война и разруха.","Его доспехи и оружие ковали кузнецы Стигии."]},"shadow_shaman":{"n":"Раста","f":["Холмовой тролль, который в детстве выступал вместе с учителем: молнии, змеи и превращение себя в курицу в финале.","После убийства учителя обратил эти фокусы против врагов и называет себя посредником между живыми и мёртвыми.","Наживал врагов, пока не скрылся под землёй, где на него напал змей-жрец Глисс.","Знает старое «лекарство от бессонницы» — превратить страдальца в овцу.","Давний друг Naga Siren; с Dark Willow договаривается, кто какой город «обрабатывает», а Troll Warlord презирает его как холмового тролля."]},"silencer":{"n":"Нортром","f":["Работает вместе с Anti-Mage на Поместье Тайлер.","Судя по биографии, его необычный дар может быть следствием близкородственных браков в роду.","Его орден враждует с орденом Chen."]},"skywrath_mage":{"n":"Драгонас","f":["Маг скайрасов, присягнувший новой королеве, которая его не жалует.","Тайно ищет лазейки в присяге, чтобы спасти изгнанную принцессу Шендельзар, которую любит.","Вероятно, сам сделал для неё Коготь Скриок.","У скайрасов есть легенда о чернокрылой Шальдере, долетевшей до божественных владык и вернувшейся с золотыми перьями.","Mars намекает на сделку с богиней Скриок, Terrorblade считает его похожим на ангела, а Dark Willow — чьей-то марионеткой."]},"slardar":{"n":"","f":["Первое Копьё Потопа, элитных стражей Глубин; получил этот титул удивительно молодым.","Носит шлем-испытание, который веками ломал претендентов, а некоторых отправлял в могилу.","Однажды убил морского дракона.","По словам Alchemist, в его теле, как у многих рыб, есть ртуть."]},"slark":{"n":"","f":["Сбежал из Тёмного рифа, подводной тюрьмы для худших преступников глубин; возможно, переоделся акулой, а помог ему Monkey King.","Связан Тёмным пактом с Тёмными, хотя говорит, что лучше бы остался в рифе.","При побеге обчистил надзирателя: стащил доспехи и ценный кинжал.","Страдает плавниковой гнилью, видит кошмары про аквариум и до сих пор прячет тайники, большую часть которых уже разграбили.","Фанат пения Naga Siren; дерётся на подпольных аренах в гротах Креи, а вместо меча иногда берёт рыбу-меч."]},"snapfire":{"n":"Беатрикс","f":["Бабушка-Кин из пустынь у Запределья; друзья зовут её Биди.","Мастер чёрного пороха и оружия; верное ружьё зовут Ол'Ракати, а отец в детстве учил её глушить рыбу динамитом.","В молодости сбежала из дома «на пару месяцев», а застряла на годы и даже ковала оружие для банды.","В банде нашла крошечную драконью жабу и в шутку назвала Мортимером; теперь он её скакун, и она надеется, что он её переживёт.","Бросила оружейное дело ради выпечки: её боевое печенье — секретный рецепт.","Тётя Timbersaw, давняя подруга Tinker и вечная соперница Sniper."]},"sniper":{"n":"Кардел Остроглаз","f":["Кин-горец, унаследовавший отцовское ружьё; может отрастить длинные усы за три дня.","Не вернётся в родной Кноллен, пока не повторит свой идеальный выстрел; обожает тамошний летний карнавал и тир.","Смотрит свысока на лучников: будущее, по его мнению, за огнестрелом.","Заказал оружейнику ружьё под свой быстрый палец, когда одной пули за выстрел стало мало.","Пьяным готов рассказать о походе в туманность Ардалан и неудаче с принцессой и плазменным пистолетом.","Соперничает со Snapfire; Bristleback и Hoodwink его не любят, как и всех Кинов."]},"spectre":{"n":"Меркуриал","f":["Пришла из одной из Семи Проекций, и неистовая энергия её родного мира просачивается сквозь её тело.","Говорит на языке Превосходных и вспоминает загадочных Трансцендентных; иногда сама себя не понимает.","Её кинжал отбрасывает на материальный мир тень, которая пугает смертных и благоволит призракам.","Когда-то с радостью приводила тени в наш мир, а теперь изо всех сил их сдерживает.","Её речь понимают только Puck и Dark Willow."]},"spirit_breaker":{"n":"Баратрум","f":["«Зверь всех миров», который странствует между Семью мирами.","Служит повелителю, давшему ему титул «Император», и отвечает только перед ним.","Его цеп выкован вокруг ядра элементальной энергии и способен пересекать планы бытия.","Битва Древних — не первая большая война, в которую он вмешивается."]},"storm_spirit":{"n":"Райджин Громокег","f":["Слияние Небожителя грома Райджина и элементалиста Громокега из-за Воющих гор.","Родня Ember, Earth и Void Spirit и Brewmaster, который просит похоронить его под Разрушенным городом.","Давний соперник Razor — вероятно, с самого момента слияния.","Весельчак и болтун; читал гримуар Warlock и злится, что богом грома называют Zeus.","Grimstroke и Monkey King ненавидят его, как и других духов."]},"sven":{"n":"","f":["Мятежный рыцарь, наполовину меранс: его отца казнили за нарушение Вигильского кодекса, мать умерла, и он остался сиротой.","Наёмный мечник, который живёт по личному кодексу чести и злится, когда его сравнивают с бандитом.","Нашёл среди обломков вигильской галеры реликвию сильнее Клинка изгоя и давно вынашивает месть Вигильским рыцарям.","Клинком Adjudicator разбил маску Juggernaut и освободил духов его предков — тот ему благодарен.","Crystal Maiden шутит про его синий оттенок, а сам он уважает Lone Druid."]},"techies":{"n":"Скви, Сплин и Спун","f":["Троица Кинов-подрывников.","Однажды пытались заменить свою тележку слоном; говорят, только один слон продержался достаточно долго.","Их пушка «Свинья» первым же выстрелом разнесла галеру, на которой стояла, и улетела в скалу под их же мастерскую.","Hoodwink ненавидит их, как и всех Кинов."]},"templar_assassin":{"n":"Ланайя","f":["Убийца Потаённого храма: её сила идёт прямо из храма и исчезнет, если она нарушит клятвы.","Считает своим хозяином Void Spirit и готовится к некоему Великому Слиянию.","Изучала архив на Фиолетовом плато после инцидента, устроенного Tinker, и труды самого Тинкера.","Любит книги, разбирается в алхимии и однажды убила королеву, оставив себе её шпильку.","Бывшая Juggernaut: он ушёл, она чувствует себя брошенной и до сих пор злится."]},"terrorblade":{"n":"","f":["Демон-разбойник, заточённый в ад внутри ада, где вечно смотрел на худшее своё отражение, пока не слился с ним.","Вернул себе пару кос, отобранных при изгнании, и занимается вымогательством.","Хочет собрать души Древних драконов, столпов творения, чтобы перекроить мир; одну, душу Ульдарака, уже заполучил.","Любит драконов, знает демона Warlock и называет себя лучшим другом Enchantress.","Pudge утверждает, что плоть демона сладкая на вкус."]},"tidehunter":{"n":"Левиафан","f":["Морской монстр из легенд кладдских моряков, которого не берут ни копья, ни мечи.","Призвал своего бога Мэльрона у Дрожащего острова и потопил флот Kunkka — с тех пор они заклятые враги.","Украл якорь Кункки, однажды съел его ботинок, а мачту его флагмана теперь использует как дубину.","Склонен к мутациям вроде новых плавников и зубов; его зубы ценятся как трофеи.","Valve официально добавила ему в поиск народное прозвище «Арбуз»."]},"shredder":{"n":"Риззрак","f":["Кин, племянник Snapfire: его мать жила с ним в Бухте Долины Предсказаний, пока ту не разрушили энты.","После этой трагедии стал параноиком, слышит голоса и боится деревьев; главные враги — Treant Protector и Nature's Prophet.","К огню равнодушен, хотя огнемёт в костюме есть.","Катапульта в его костюме, кажется, всегда срабатывает слишком поздно."]},"tinker":{"n":"Боуш","f":["Кин с учёной степенью, основавший лабораторию под Фиолетовым плато: дроны, лазерные резаки, самонаводящиеся ракеты.","Эксперимент вышел из-под контроля, и Боуш остался на плато один; Juggernaut винит его во всех погибших.","Из той же технологии порталов сделал себе ботинки-телепорты.","Считает алхимию лженаукой, а алхимиков психами; дружит со Snapfire.","Знает о загадочной Семиминутной войне и, похоже, в ней участвовал."]},"tiny":{"n":"","f":["Каменный великан неизвестного происхождения, который, похоже, вырос из маленького камешка; намекает, что Enchantress когда-то пускала его «блинчиком» по реке.","Умеет оживлять скалы и черпать силу из ледников.","Earth Spirit обещает после битвы рассказать ему, откуда он взялся, а Elder Titan знает его происхождение.","Владеет артефактом «Кристальная Дриада», в который превратился скипетр Аганима в каменных руках."]},"treant":{"n":"Руфтреллен","f":["Единственный энт-защитник, чьё имя известно, и единственный, кто покинул родные леса; деньги и предметы ему пришлось осваивать с нуля.","Носит на лбу камень неизвестного назначения.","Энты, похожие на его сородичей, разрушили Бухту Долины Предсказаний, поэтому Timbersaw считает его главным врагом.","Совершил что-то великое в Розолисте и ушёл оттуда; Dark Willow считает это глупым, но достойным восхищения.","Настолько силён, что даже паразитическая лоза чудо-дерева, губящая слабые деревья, ему не вредит."]},"troll_warlord":{"n":"Джа'ракал","f":["Высокомерный тролль, который считает, что невинных не бывает, но модно приодеться не прочь.","Презирает Shadow Shaman как «низшего» холмового тролля, а Dazzle и Huskar — потому что видит в них себя.","Ненавидит Кинов и, по неизвестной причине, торговцев.","Свои топоры забрал у пары убитых охотников-Оглоди."]},"tusk":{"n":"Имир","f":["Его зовут Ужасом из Барьера, Снежным Комом из Кобальта и Железной Рыбой — в честь перчатки в форме старой боксёрской груши-рыбы; для друзей он просто Таск.","Редко спускается на юг; дружит с Племенем Морозного Железа и навещает их каждую зиму.","На спине носит напарника-пингвина Виски.","Старый друг Crystal Maiden — в детстве они играли в снежки.","Подрался в таверне с вышибалой — им был Bristleback; считает, что после драки хорошим тоном угостить всех выпивкой.","Любит делать комплименты героям с бивнями."]},"abyssal_underlord":{"n":"Врогрош","f":["Владыка Орды Бездны из подземного города Азийог, стены которого строят из костей рабов.","Всегда идёт во главе армии и вешает черепа врагов в Азийоге.","Напал на Стоунхолл и столкнулся там с Legion Commander и Бронзовым легионом.","Abyssal Blade, похоже, выковали кузнецы его орды, а сам он когда-то им владел.","Грозится сжечь леса Luna и Mirana — Серебристый лес."]},"undying":{"n":"Дердж","f":["Эмиссар Мёртвого бога, избранный среди нежити, чтобы говорить с живыми от имени владыки.","Его Панихида поднимает мёртвых из-под земли и приближает распад мира.","Носит доспехи народа, к которому принадлежал при жизни.","Anti-Mage поклялся уничтожить всех слуг Мёртвого бога, поэтому ненавидит его.","Знает истинное имя Invoker; Dark Willow украла что-то ценное из его гробницы и не собирается возвращать."]},"ursa":{"n":"Ульфсаар","f":["Зимой вместе с братьями-урсами охраняет горы к северу от родины, пока спят медвежата.","Чтит Сангстратов — исчезнувшую расу хранителей, чьи земли теперь занимают урсы.","Когда-то учился у Lone Druid и откусил наставнику палец.","Носит броню из костей бритвенного змея и ожерелье из зубов чолгар; после Маски Владимира одержим охотой на Рошана.","Взял под опеку осиротевшего медвежонка, хотя пророчества сулят тому стать тираном.","Дружит с Enchantress и презирает алхимию и всё, что смешивает природные формы."]},"vengefulspirit":{"n":"Шендельзар","f":["Изгнанная принцесса скайрасов; поклоняется богине мести Скриок и богине своего народа Авиливе.","Skywrath Mage тайно влюблён в неё и, вероятно, сделал для неё Коготь Скриок.","Когда-то восхищалась крыльями Puck."]},"venomancer":{"n":"Лесайл","f":["Ещё до Кислотных джунглей острова Джиди знал их растения и зверей.","Случайно съел кокон мотылька фраджан, пытаясь использовать орхидею, — так и стал тем, кто он есть.","Однажды отлёживался в расщелине, где поклонники древнего бога-змея Актока приняли его за посланника своего бога.","Распускает небылицы об острове Джиди, чтобы заманивать туда путешественников и съедать их."]},"viper":{"n":"Незердрейк","f":["Низший дракон, бывший питомец Pugna, вырвавшийся на свободу; теперь сам хочет завести колдуна в качестве питомца.","От бывшего хозяина подхватил страсть к улучшению своего тела с помощью магии и чужих страданий.","Ненавидит магов из-за своего прошлого.","Lifestealer уверяет, что на вкус он как курица."]},"visage":{"n":"Некро'лик","f":["Страж Узкого лабиринта, как и Razor; говорят, его рабская служба страшнее участи его жертв.","Не выносит нежить и собирательство душ, которым занимается Shadow Fiend.","Похоже, уже не раз отправлял Lion обратно в ад.","Его вид пугает многих героев, включая Dark Willow."]},"void_spirit":{"n":"Инай","f":["Первый небожитель, воплощение пустоты; принял смертный облик и построил Потаённый храм для своего тела и артефактов.","Храм выстроен по чертежам Корумитов — забытого ордена учёных-воинов, о котором помнят только он и Invoker.","Ему служат Templar Assassin и, не всегда послушно, Spectre; Nyx Assassin он тоже зовёт к себе.","Мечтает объединить всех небожителей в Великом Слиянии; это он подстроил заклинание, призвавшее Райджина для Storm Spirit.","Монахи Турстаркури следовали его учению, но, по его словам, поняли его неправильно.","Отец Dark Willow потратил почти всё золото на поиски его храма — безуспешно."]},"warlock":{"n":"Дэмнок Лэнник","f":["Неделю творил заклинания, чтобы пробить проход за пределы мира смертных, и оттуда явился его демон.","Годами учился произносить истинное имя Наблюдателя, но у того, как выяснилось, нет языка.","На Озкавоше говорит плохо, а почерк у него ужасный.","Storm Spirit читал его гримуар и отзывается о нём нелестно, Puck считает, что там полно ошибок, а Terrorblade знает его демона."]},"weaver":{"n":"Скитскур","f":["Один из Ткачей — существ-насекомых, которые чинят ткань мироздания и не дают ей разорваться.","Ткачи защищают вселенную от порождений тьмы, грызущих её нити.","Его антенны чувствуют любые изменения в материи мира.","Проскользнул сквозь дыру во времени и нашёл там невиданный артефакт, ставший его оружием.","Dawnbreaker знает Ткачей и удивлена, что один из них пришёл на Битву Древних."]},"windrunner":{"n":"Лиралей","f":["Никогда не знала своей семьи; Grimstroke считает, что ей и не стоит.","Сражается за мир, а не за золото, и любит произносить вдохновляющие речи; собирает огромную библиотеку.","Дружит с хищными птицами, а её стрелы пробивают деревья насквозь.","Помогала защищать Тёмный риф и спасла обречённый лес в Очаге Ньорда, где царит вечная весна.","Говорит, что Puck как-то связан с её предками.","Вечная соперница Drow Ranger; дружит с Beastmaster, Lycan и Enchantress."]},"winter_wyvern":{"n":"Аурот","f":["Древнейшая из Древних драконов — и она, и Spectre это подтверждают.","Поэтесса: в её лечебном коконе разум пленника наполняется образами из любимой поэмы.","Snapfire обожает её стихи, Grimstroke предлагает сотрудничество, а Dark Willow мечтает о книгах из её коллекции.","Terrorblade, как любитель драконов, к ней благосклонен."]},"witch_doctor":{"n":"Жарвакко","f":["Его магия сомнительного происхождения, но связана с легендой о великом целителе Ауалебе, который считал беды своего народа симптомами болезни поглубже.","Одна мартышка подсмотрела его обряды и принесла это знание своему роду, за что её изгнали как безумную.","Владеет яйцом легендарного штормового ворона с вершин Префектовых гор — мощным источником магии.","Huskar уважает его как ценителя жизненной силы."]},"skeleton_king":{"n":"Остарион","f":["Раньше звался Королём-Скелетом и переродился Королём-Призраком в Призрачную ночь; его до сих пор называют Костяным Лордом.","Веками строил королевство из останков врагов, считая, что будет жить, пока растут его башни.","Забирает короны убитых королей и носит их; меч ему сделали из костей и доспехов павших правителей.","Убил Рыцаря Ужаса, дракона-нежить Амбиндерата и герцога Левинталя, забрав себе их трофеи.","Открыто флиртует с Queen of Pain, но взаимности не получает."]},"zuus":{"n":"Повелитель небес","f":["Бог из пантеона с братьями; его жена урезала ему силы, но часть небесной мощи он всё ещё черпает через Дары Целестарра.","Собирает артефакты, чтобы вернуть былое могущество, например шлем клана Молотов Целестарра.","Отец Mars, который поклялся свергнуть его пантеон.","Высокомерен даже для бога; Monkey King его не выносит, а Dawnbreaker сочувствует ему как такой же утратившей силу."]}};
